-- Préparé en local. À appliquer uniquement lors de la publication groupée approuvée.
-- Sauvegarder les tables projects, project_category_links et site_settings auparavant.
begin;
alter table public.projects add column if not exists city_code text;
alter table public.projects add column if not exists department_code text;
update public.projects set city = 'Puget-Théniers', city_code = '06099', department_code = '06' where slug = 'creation-d-un-mur-de-soutenement-en-betonflore';
update public.projects set city = 'La Croix-Valmer', city_code = '83048', department_code = '83' where slug = 'voirie-reseaux-amenagement-exterieur-villa';
update public.projects set city = 'Fréjus', city_code = '83061', department_code = '83' where slug = 'creation-regards-caniveaux-cour-recreation';
update public.projects set city = 'Saint-Raphaël', city_code = '83118', department_code = '83' where slug = 'refection-parking-enrobe-saint-raphael';
do $location_constraint$ begin if not exists (select 1 from pg_constraint where conname = 'projects_location_pair' and conrelid = 'public.projects'::regclass) then alter table public.projects add constraint projects_location_pair check ((city_code is null and department_code is null) or (city_code is not null and department_code is not null and city_code ~ '^[0-9A-Z]{5}$' and department_code ~ '^([0-9]{2,3}|2A|2B)$')); end if; end $location_constraint$;
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'voirie-reseaux-amenagement-exterieur-villa' and c.slug = 'assainissement' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'voirie-reseaux-amenagement-exterieur-villa' and c.slug = 'reseaux' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'voirie-reseaux-amenagement-exterieur-villa' and c.slug = 'amenagements-exterieurs' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'creation-regards-caniveaux-cour-recreation' and c.slug = 'assainissement' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'creation-regards-caniveaux-cour-recreation' and c.slug = 'voirie' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'refection-parking-enrobe-saint-raphael' and c.slug = 'terrassement' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
insert into public.project_category_links (project_id, category_id) select p.id, c.id from public.projects p cross join public.project_categories c where p.slug = 'creation-d-un-mur-de-soutenement-en-betonflore' and c.slug = 'terrassement' and not exists (select 1 from public.project_category_links l where l.project_id = p.id and l.category_id = c.id);
update public.project_categories set name = 'Réseaux secs et humides' where slug = 'reseaux';
update public.project_categories set name = 'Aménagements extérieurs' where slug = 'amenagements-exterieurs';
update public.project_categories set name = 'Démolition / reprise' where slug = 'demolition-reprise';
update public.site_settings set value = value || $frtp_seo${"heroEyebrow":"Fréjus - Var - Alpes-Maritimes","heroPanelEyebrow":"Vos travaux dans le 83 et le 06","heroPanelTitle":"Préparer le terrain, raccorder les réseaux et aménager les accès.","heroPanelItems":["Terrassement et préparation des sols","Réseaux secs et humides","Voirie et aménagements extérieurs"],"homeActivitiesTitle":"Terrassement, réseaux et voirie : les travaux que nous réalisons.","homeActivitiesText":"Terrassement, réseaux enterrés, parkings et accès : consultez le détail de nos prestations.","homeProjectsTitle":"Nos chantiers dans le Var et les Alpes-Maritimes.","homeProjectsText":"Voirie, réseaux, soutènement et aménagements extérieurs.","reviewsText":"Consultez les témoignages de nos clients sur la fiche Google FRTP.","reviewsGoogleUrl":"https://www.google.com/maps?cid=5562041291635957611","companyTitle":"FRTP, entreprise de travaux publics dans le Var et les Alpes-Maritimes.","companyIntro":"FRTP est une entreprise de travaux publics basée à Fréjus. Nous intervenons dans le Var et les Alpes-Maritimes pour les travaux de terrassement, de voirie et réseaux divers, d’assainissement, de réseaux secs et humides, d’aménagements extérieurs, de soutènement et de démolition ciblée. Nos prestations s’adressent aux particuliers, aux copropriétés, aux entreprises et aux collectivités.","companyCards":[{"title":"Travaux dans le Var et les Alpes-Maritimes","text":"Basée à Fréjus, FRTP propose l’ensemble de ses prestations dans les deux départements."},{"title":"Terrassement, voirie et VRD","text":"Préparation des terrains, fouilles, tranchées, fonds de forme, accès, parkings, bordures et revêtements."},{"title":"Réseaux et assainissement","text":"Réseaux d’eau potable, d’eaux usées et pluviales, fourreaux télécom et électriques, regards, caniveaux et raccordements."},{"title":"Aménagements extérieurs et soutènement","text":"Cours, cheminements, pavage, abords, reprise de niveaux et ouvrages de soutènement."}],"serviceArea":["Fréjus","Saint-Raphaël","Roquebrune-sur-Argens","Puget-sur-Argens","La Croix-Valmer","Puget-Théniers","Le Cannet","Cannes","Alpes-Maritimes","Var"],"activitiesPageText":"FRTP réalise des travaux de terrassement, de voirie, de réseaux et d’assainissement dans le Var et les Alpes-Maritimes.","projectsPageTitle":"Chantiers réalisés dans le Var et les Alpes-Maritimes.","projectsPageText":"Voirie, réseaux, soutènement et aménagements extérieurs réalisés dans le Var et les Alpes-Maritimes.","newsPageText":"Informations et archives de l’entreprise FRTP. Pour suivre les travaux réalisés, consultez nos réalisations.","beforeAfterTitle":"Nos interventions en photos, avant et après les travaux.","beforeAfterText":"Comparez l’état initial et le résultat des travaux.","stats":[{"label":"Var, secteur principal","value":"83"},{"label":"Interventions Alpes-Maritimes","value":"06"},{"label":"Familles de prestations","value":"7"},{"label":"Étude personnalisée","value":"100 %"}],"reviewsTitle":"Les avis de nos clients","methodTitle":"Avant les travaux","contactTitle":"Demander un devis"}$frtp_seo$::jsonb, updated_at = now() where key = 'studio';
update public.site_settings set value = jsonb_set(value, '{activities}', (select jsonb_agg(a || jsonb_build_object('interventionExample', coalesce($frtp_seo${"terrassement":"À La Croix-Valmer, les terrassements préparent les tranchées techniques, les fonds de forme et les accès d’une villa. À Saint-Raphaël, le terrassement de la structure précède la réfection d’un parking en enrobé.","vrd":"Le lot VRD de la villa de La Croix-Valmer associe réseaux secs et humides, voirie d’accès et aménagements extérieurs. À Fréjus, la création de regards et caniveaux complète la reprise d’une cour de récréation.","assainissement":"À Fréjus, la création de regards à grille et de caniveaux permet le raccordement au réseau pluvial existant dans une cour de récréation. Le chantier de La Croix-Valmer comprend aussi des réseaux d’eaux usées et d’eaux pluviales.","voirie":"À Saint-Raphaël, la réfection d’un parking comprend la dépose de l’ancien enrobé, une nouvelle structure de voirie, le revêtement noir et le marquage au sol. À La Croix-Valmer, l’accès carrossable fait partie du lot VRD de la villa.","reseaux":"À La Croix-Valmer, les travaux comprennent l’eau potable, les eaux usées et pluviales, les télécommunications, les courants forts et faibles et les alimentations techniques de la villa.","amenagements-exterieurs":"À Puget-Théniers, FRTP réalise un mur de soutènement paysager en bétonflore et une clôture rigide à la résidence La Colette. À La Croix-Valmer, le chantier comprend du pavage en travertin et des cheminements extérieurs.","demolition-reprise":"La réfection du parking de Saint-Raphaël commence par la dépose de l’enrobé existant, avant la reprise de la structure, la pose du nouveau revêtement et le marquage au sol."}$frtp_seo$::jsonb ->> (a ->> 'slug'), a ->> 'interventionExample')) order by ord) from jsonb_array_elements(value -> 'activities') with ordinality as entries(a, ord))), updated_at = now() where key = 'studio';
update public.site_settings set value = (select jsonb_agg(item || coalesce($frtp_seo${"abords-villa":{"city":"Saint-Raphaël","cityCode":"83118","departmentCode":"83","category":"Aménagements extérieurs","title":"Reprise d'abords de villa"},"talus":{"city":"Le Cannet","cityCode":"06030","departmentCode":"06","category":"Terrassement","title":"Confortement et reprise de talus"},"55993e56-eb4a-4a2e-916a-39df8b6bd985":{"city":"La Croix-Valmer","cityCode":"83048","departmentCode":"83","category":"Aménagements extérieurs","title":"Pavage carrossable en travertin (vue 1)"},"96a86423-b058-4f03-86e3-3e5b5de47a6f":{"city":"La Croix-Valmer","cityCode":"83048","departmentCode":"83","category":"Aménagements extérieurs","title":"Pavage carrossable en travertin (vue 2)"},"8cceafbb-0c34-49c6-8d28-e48e0aecc738":{"city":"La Croix-Valmer","cityCode":"83048","departmentCode":"83","category":"Aménagements extérieurs","title":"Pavage carrossable en travertin (vue 3)"}}$frtp_seo$::jsonb -> (item ->> 'id'), '{}'::jsonb) order by ord) from jsonb_array_elements(value) with ordinality as entries(item, ord)), updated_at = now() where key = 'before_after_items';
commit;
